UPDATE TB_PRD_TAB_SLIDE
   SET TITLE = #{title}, SUB_TEXT = #{subText}, BADGE_TEXT = #{badgeText}, BG_COLOR = #{bgColor},
       IMAGE_URL = #{imageUrl}, IMAGE_ALT = #{imageAlt}, PRODUCT_CD = #{productCd}, LINK_URL = #{linkUrl},
       CHANNELS = #{channels}, START_DT = #{startDt}, END_DT = #{endDt}, SORT_ORD = #{sortOrd}, USE_YN = #{useYn},
       UPD_AT = #{updAt}, UPD_BY = #{updBy}
 WHERE SLIDE_ID = #{slideId}

